mapper.select:
select i.invoice_id, i.invoice_no, i.order_id, i.applicant_id, i.invoice_type, i.email, i.title, i.tax_no, i.amount, i.invoice_url, i.status, i.reject_reason, i.invoice_time, i.created_at, i.updated_at, o.order_no, w.title as work_title from sys_invoice i left join sys_order o on i.order_id = o.order_id left join sys_work w on o.work_id = w.work_id
AND i.status = #{status} AND i.applicant_id = #{applicantId} AND i.invoice_type = #{invoiceType}
order by i.created_at desc
